import json
import os
from pathlib import Path
from typing import Union, Any, Callable, Dict

def update_json(path: Union[str, Path], transformer: Callable[[Dict[str, Any]], Dict[str, Any]],
                default: Dict[str, Any] = None) -> Dict[str, Any]:
    """Atomically rewrite a JSON file with a transformer applied to its contents.

    Args:
        path: JSON file path.
        transformer: Function that maps the current dict to the new dict.
        default: Optional default used when the file is missing or unparseable.

    Returns:
        The new dict value that was written to disk.

    Examples:
        >>> update_json("nope.json", lambda d: {}, default={}) == {}
        True
    """
    p = Path(path)
    base: Dict[str, Any] = {}
    if p.exists():
        try:
            loaded = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                base = loaded
        except (json.JSONDecodeError, OSError):
            base = dict(default) if isinstance(default, dict) else {}
    elif default is not None and isinstance(default, dict):
        base = dict(default)
    new_data = transformer(dict(base))
    if p.parent and not p.parent.exists():
        p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    try:
        tmp.write_text(json.dumps(new_data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        os.replace(tmp, p)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass
    return new_data


def get_json_value(path: Union[str, Path], key: str, default: Any = None) -> Any:
    """Return a single key from a JSON object file, with a fallback.

    Args:
        path: JSON file path.
        key: Key to look up.
        default: Value returned when the key or file is absent.

    Returns:
        The decoded value or default.

    Examples:
        >>> get_json_value("missing.json", "k", default=1)
        1
    """
    p = Path(path)
    if not p.exists():
        return default
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return default
    if isinstance(data, dict):
        return data.get(key, default)
    return default

