from collections import deque

def ladder_length(begin, end, words):
    s = set(words)
    queue = deque([(begin, 1)])
    while queue:
        word, depth = queue.popleft()
        if word == end:
            return depth
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nw = word[:i] + c + word[i+1:]
                if nw in s:
                    s.remove(nw)
                    queue.append((nw, depth + 1))
    return 0
