import functools

def memo(func):
    """Cache function results keyed by positional args."""
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    wrapper.cache_clear = cache.clear
    return wrapper

