from typing import Dict, Any

KV_RE = re.compile(r"""([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(\d+(?:\.\d+)?|'[^']*'|"[^"]*")""")

def parse_simple_object(text: str) -> Dict[str, Any]:
    """Parse a flat JS-style object literal into a dict.

    Args:
        text: Object string like '{a:1, b:2}'.

    Returns:
        Dict of key->value (numbers become int/float, quoted become str).

    Examples:
        >>> sorted(parse_simple_object("{a:1, b:'two', c:3.5}").items())
        [('a', 1), ('b', 'two'), ('c', 3.5)]
        >>> parse_simple_object("{}")
        {}
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    inner = text.strip()
    if inner.startswith("{") and inner.endswith("}"):
        inner = inner[1:-1]
    out: Dict[str, Any] = {}
    for match in KV_RE.finditer(inner):
        key, raw = match.group(1), match.group(2)
        if raw.startswith("'") or raw.startswith('"'):
            out[key] = raw[1:-1]
        elif "." in raw:
            out[key] = float(raw)
        else:
            out[key] = int(raw)
    return out

